using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using VintageCollector.Media;
using VintageCollector.Runtime;
namespace VintageCollector.EditorTools {
 public static class SuppliedArtNativeBuild {
  public const string Scene="Assets/VintageCollector/Scenes/BootstrapSuppliedExpansionArt.unity";
  public const string Generation="b98f62fecb5239f3bbc7cf78273c2b8f209488f40d5362ba4519824a419058fb";
  [Serializable] public sealed class Attestation {public string root,stage,candidate,action,rootPinsSHA,stagePinsSHA,metaAllowlistSHA,builderInputSHA;}
  [Serializable] public sealed class MetaAllowance {public string[] assets;public string[] folders;}
  [Serializable] public sealed class Face {public string canonicalId,texture;}
  [Serializable] public sealed class Wrapper {public string role,texture;}
  [Serializable] public sealed class Profile {public string printingId;public Face[] faces;public Wrapper[] wrappers;}
  [Serializable] public sealed class Input {public string assetRoot,generationId;public Profile[] profiles;}
  [Serializable] public sealed class Pin {public string path,sha256;}
  [Serializable] public sealed class Evidence {public bool passed;public int warnings,errors;public string sceneGuid;public Pin[] compilerPins,candidatePins;}
  static string Project {get{return Path.GetDirectoryName(Application.dataPath);}}
  static string Full(string s){return Path.GetFullPath(s).TrimEnd('\\','/').Replace('\\','/');}
  public static Dictionary<string,string> Pins(string file){var d=new Dictionary<string,string>(StringComparer.Ordinal);foreach(string line in File.ReadAllLines(file)){var s=line.Split('\t');if(s.Length!=2||!System.Text.RegularExpressions.Regex.IsMatch(s[1],"^[0-9a-f]{64}$")||s[0].Split('/').Any(x=>x==""||x=="."||x=="..")||s[0].Contains("\\")||s[0].Contains(":")||s[0].StartsWith("/")||!new[]{"Assets","Packages","ProjectSettings"}.Contains(s[0].Split('/')[0])||d.ContainsKey(s[0]))throw new InvalidOperationException("Invalid full pin TSV");d.Add(s[0],s[1]);}if(d.Count==0)throw new InvalidOperationException("Empty pins");return d;}
  public static void RequireBatch(bool batch){if(!batch)throw new InvalidOperationException("Batch operational entrypoint only");}
  static Attestation Admit(string action){
   RequireBatch(Application.isBatchMode);SuppliedArtBuildPolicy.Boundaries(Project); // recursive reparse checks FIRST
   string expected="{\"owner\": \"supplied-art-exact-source-v1\", \"root\": \""+Full(SuppliedArtBuildPolicy.Root)+"\"}";
   if(File.ReadAllText(Path.Combine(Project,".supplied-art-owned-stage.json"))!=expected)throw new InvalidOperationException("Exact Python stage marker required");
   string token=null;foreach(string a in Environment.GetCommandLineArgs())if(a.StartsWith("--supplied-art-native-token=",StringComparison.Ordinal)){if(token!=null)throw new InvalidOperationException("Duplicate native token");token=a.Substring("--supplied-art-native-token=".Length);}
   string file=Path.Combine(Project,".supplied-art-native-attestation.json");
   if(token==null||token!=Phase5BuildPolicy.Hash(file))throw new InvalidOperationException("Trusted parent CLI attestation token required; menus alone are never authority");
   var v=JsonUtility.FromJson<Attestation>(File.ReadAllText(file));
   if(v==null||v.root!=Full(SuppliedArtBuildPolicy.Root)||v.stage!=Full(Project)||v.candidate!=Full(Path.Combine(v.root,SuppliedArtBuildPolicy.CandidateRelative))||v.action!=action)throw new InvalidOperationException("Attested exact action/boundaries");
   string[] names={".supplied-art-root-pins.tsv",".supplied-art-stage-pins.tsv",".supplied-art-meta-allowlist.json",".supplied-art-builder-input.json"};string[] hashes={v.rootPinsSHA,v.stagePinsSHA,v.metaAllowlistSHA,v.builderInputSHA};for(int i=0;i<names.Length;i++)if(Phase5BuildPolicy.Hash(Path.Combine(Project,names[i]))!=hashes[i])throw new InvalidOperationException("Attested data drift");
   var source=Pins(Path.Combine(Project,names[0]));var staged=Pins(Path.Combine(Project,names[1]));
   var allowance=JsonUtility.FromJson<MetaAllowance>(File.ReadAllText(Path.Combine(Project,names[2])));if(allowance==null||allowance.assets==null||allowance.folders==null)throw new InvalidOperationException("Explicit file/folder metadata allowlist required");
   SuppliedArtBuildPolicy.AdmitClosure(v.root,Project,source,staged,allowance.assets,allowance.folders,action);return v;
  }
  static string ProfilePath(int i){return "Assets/VintageCollector/Media/Phase5/"+(i==0?"Jungle":"Fossil")+"SuppliedImageProfile.asset";}
  static Input Read(){var v=JsonUtility.FromJson<Input>(File.ReadAllText(Path.Combine(Project,".supplied-art-builder-input.json")));if(v==null||v.generationId!=Generation||v.assetRoot!="Assets/Supplied/ExpansionSetMaterials/generations/"+Generation||v.profiles==null||v.profiles.Length!=2)throw new InvalidOperationException("Stable exact generation");var paths=new HashSet<string>();var ids=new HashSet<string>();for(int i=0;i<2;i++){var p=v.profiles[i];if(p.printingId!=(i==0?"jungle":"fossil")+"-en-unlimited1999"||p.faces.Length!=(i==0?64:62)||p.wrappers.Length!=3)throw new InvalidOperationException("Complete canonical profile");foreach(var f in p.faces){PathFor(v,f.texture);if(!paths.Add(f.texture)||!ids.Add(f.canonicalId))throw new InvalidOperationException("Duplicate row");}for(int j=0;j<3;j++){PathFor(v,p.wrappers[j].texture);if(p.wrappers[j].role!=((char)('A'+j)).ToString()||!paths.Add(p.wrappers[j].texture))throw new InvalidOperationException("Wrapper roles");}}return v;}
  static string PathFor(Input v,string rel){if(string.IsNullOrEmpty(rel)||rel.Contains("..")||rel.Contains("\\")||rel.Contains(":")||rel.StartsWith("/")||!rel.EndsWith(".png",StringComparison.Ordinal))throw new InvalidOperationException("Unsafe texture");return v.assetRoot+"/"+rel;}
  static void Absent(string path){if(File.Exists(Path.Combine(Project,path))||File.Exists(Path.Combine(Project,path+".meta")))throw new InvalidOperationException("Never overwrite authored assets");}
  public static void CreateAssets(){Admit("CreateAssets");var input=Read();for(int i=0;i<2;i++)Absent(ProfilePath(i));
   foreach(var p in input.profiles){var all=p.faces.Select(f=>f.texture).Concat(p.wrappers.Select(w=>w.texture));foreach(string n in all){string path=PathFor(input,n);var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)throw new InvalidOperationException("Imported PNG required");importer.npotScale=TextureImporterNPOTScale.None;importer.mipmapEnabled=false;importer.isReadable=true;importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}}
   for(int i=0;i<2;i++){var p=input.profiles[i];var asset=ScriptableObject.CreateInstance<SuppliedCardArtProfile>();asset.printingId=p.printingId;asset.displayLabel=i==0?"Jungle supplied visual substitutes":"Fossil supplied visual substitutes";asset.cards=p.faces.Select(f=>new SuppliedCardArtRow{cardId=f.canonicalId,face=AssetDatabase.LoadAssetAtPath<Texture2D>(PathFor(input,f.texture))}).ToArray();AssetDatabase.CreateAsset(asset,ProfilePath(i));}AssetDatabase.SaveAssets();ValidateAssets(input);
  }
  static void ValidateAssets(Input input){for(int i=0;i<2;i++){var p=AssetDatabase.LoadAssetAtPath<SuppliedCardArtProfile>(ProfilePath(i));if(p==null||p.printingId!=input.profiles[i].printingId||p.cards.Length!=input.profiles[i].faces.Length)throw new InvalidOperationException("Native profile closure");for(int j=0;j<p.cards.Length;j++){var row=p.cards[j];if(row.cardId!=input.profiles[i].faces[j].canonicalId||row.face==null||row.face.width!=600||row.face.height!=825||AssetDatabase.GetAssetPath(row.face)!=PathFor(input,input.profiles[i].faces[j].texture))throw new InvalidOperationException("Native face binding");}}}
  static OpeningGame Open(string path){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var games=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<OpeningGame>(true)).ToArray();if(games.Length!=1)throw new InvalidOperationException("Exactly one real controller");return games[0];}
  public static void CreateBootstrap(){Admit("CreateBootstrap");Absent(Scene);var input=Read();ValidateAssets(input);if(!AssetDatabase.CopyAsset(Phase5Build.ScenePath,Scene))throw new IOException("Clone accepted scene failed");var game=Open(Scene);var host=game.GetComponent<Phase5MediaHost>();if(host==null)throw new InvalidOperationException("Accepted native media owner");host.suppliedCardArtProfiles=new[]{AssetDatabase.LoadAssetAtPath<SuppliedCardArtProfile>(ProfilePath(0)),AssetDatabase.LoadAssetAtPath<SuppliedCardArtProfile>(ProfilePath(1))};for(int i=0;i<2;i++){var config=game.phase5Sets.Single(c=>c.printingId==input.profiles[i].printingId);config.wrapperFronts=input.profiles[i].wrappers.Select(w=>AssetDatabase.LoadAssetAtPath<Texture2D>(PathFor(input,w.texture))).ToArray();}game.gameObject.AddComponent<VintageCollector.Verification.SuppliedArtSmokeProbe>();EditorSceneManager.MarkSceneDirty(game.gameObject.scene);if(!EditorSceneManager.SaveScene(game.gameObject.scene,Scene))throw new IOException("Save cloned scene");AssetDatabase.SaveAssets();ValidateScene(input);PrepareRecipeCore();DiskRecipe();}
  static void ValidateScene(Input input){ValidateAssets(input);var game=Open(Scene);var profiles=game.GetComponent<Phase5MediaHost>().suppliedCardArtProfiles;if(profiles==null||profiles.Length!=2)throw new InvalidOperationException("Reopened host profiles");for(int i=0;i<2;i++)if(AssetDatabase.GetAssetPath(profiles[i])!=ProfilePath(i)||AssetDatabase.AssetPathToGUID(ProfilePath(i))=="")throw new InvalidOperationException("Native profile GUID binding");if(AssetDatabase.AssetPathToGUID(Scene)=="")throw new InvalidOperationException("Scene GUID");foreach(var p in input.profiles){var set=game.phase5Sets.Single(c=>c.printingId==p.printingId);for(int j=0;j<3;j++)if(AssetDatabase.GetAssetPath(set.wrapperFronts[j])!=PathFor(input,p.wrappers[j].texture))throw new InvalidOperationException("Wrapper binding");}}
  static void PrepareRecipeCore(){if(EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Root release defaults required; never rewrite settings");byte[] recipe=SuppliedArtBuildPolicy.RecipeBytes(SuppliedArtBuildPolicy.Root,Project);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Scene,true)};File.WriteAllBytes(Path.Combine(Project,SuppliedArtBuildPolicy.Settings),recipe);}

  static void DiskRecipe(){string file=Path.Combine(Project,"ProjectSettings/EditorBuildSettings.asset");string text=File.ReadAllText(file);string guid=AssetDatabase.AssetPathToGUID(Scene);if(guid.Length!=32||!text.Contains("path: "+Scene)||!text.Contains("guid: "+guid)||!text.Contains("enabled: 1"))throw new InvalidOperationException("EditorBuildSettings disk recipe not flushed: parent must stop, never relax pins");}
  public static void PrepareReleaseRecipe(){Admit("CreateBootstrap");PrepareRecipeCore();DiskRecipe();}
  public static void BuildWindows(){var a=Admit("BuildWindows");var input=Read();ValidateScene(input);if(EditorBuildSettings.scenes.Length!=1||EditorBuildSettings.scenes[0].path!=Scene||!EditorBuildSettings.scenes[0].enabled||EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Frozen release recipe required before pins");DiskRecipe();var before=Phase5BuildPolicy.AllInputs(Project);Directory.CreateDirectory(a.candidate);File.WriteAllText(Path.Combine(a.candidate,".supplied-art-candidate-owner.txt"),"supplied-art-exact-source-v1\n"+a.root+"\n");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Scene},target=BuildTarget.StandaloneWindows64,locationPathName=Path.Combine(a.candidate,"VintageCardCollector.exe"),options=BuildOptions.None});SuppliedArtBuildPolicy.ExactClosure(Project,before);if(report.summary.result!=BuildResult.Succeeded||report.summary.totalErrors!=0||report.summary.totalWarnings!=0)throw new InvalidOperationException("Native build must have zero warnings/errors");var candidate=new List<Pin>();Phase5BuildPolicy.RequireRegularTree(a.candidate);foreach(string p in Directory.GetFiles(a.candidate,"*",SearchOption.AllDirectories))candidate.Add(new Pin{path=Full(p).Substring(a.candidate.Length+1),sha256=Phase5BuildPolicy.Hash(p)});File.WriteAllText(Path.Combine(Project,".supplied-art-build-report.json"),JsonUtility.ToJson(new Evidence{passed=true,compilerPins=before.Select(p=>new Pin{path=p.Key,sha256=p.Value}).ToArray(),candidatePins=candidate.ToArray(),sceneGuid=AssetDatabase.AssetPathToGUID(Scene)},true));}
 }
}
